import urllib.request, re
h = {'User-Agent':'Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0 Safari/537.36', 'Accept':'text/html'}
col = ['2IB5','4KGE','4Q7T','5JZL','6AA7','3ADF','5WJ2','3M22','2H5Q','3MGF','5Y01','2VZX','4CQH','1YZW','1H6R']
for i in col:
    try:
        r1 = urllib.request.Request('https://www.fpbase.org/search/?q='+i, headers=h)
        t1 = urllib.request.urlopen(r1).read().decode()
        m = re.search(r'canonical\\?"? href=\"(https://www.fpbase.org/protein/[^\s\"?]+)', t1)
        if not m:
            print(i, 'NOCANON'); continue
        url = m.group(1)
        t2 = urllib.request.urlopen(urllib.request.Request(url, headers=h)).read().decode()
        vals = re.findall(r'(Excitation|Emission)\\s*<[^>]*>\\s*([0-9]+)', t2)
        if not vals:
            vals = re.findall(r'(Excitation|Emission)[^0-9]{0,60}([0-9]{3})', t2)
        print(i, m.group(1), vals[:4])
    except Exception as e:
        print(i, 'ERR', e)
